    UPDATE target
    SET target.Title=src.Title,
        target.Description=src.Description,
        target.RoleId=r.Id,
        target.WorkflowBucketId=b.Id,
        target.Category=src.Category,
        target.Frequency=src.Frequency,
        target.Priority=src.Priority,
        target.ToolCoverageLevel=src.ToolCoverageLevel,
        target.TriggerContext=src.TriggerContext,
        target.McemStage=src.McemStage,
        target.DurationMinutes=src.DurationMinutes,
        target.BusinessOutcome=src.BusinessOutcome,
        target.BeginnerPrompt=src.BeginnerPrompt,
        target.AdvancedPrompt=src.AdvancedPrompt,
        target.SuggestedOutputs=src.SuggestedOutputs,
        target.SortOrder=src.SortOrder,
        target.IsActive=src.IsActive,
        target.UpdatedAtUtc=SYSUTCDATETIME()
    FROM dbo.Activities target
    INNER JOIN @Source src ON src.ExternalId=target.ExternalId
    INNER JOIN dbo.Roles r ON r.ExternalId=src.RoleExternalId
    INNER JOIN dbo.WorkflowBuckets b ON b.ExternalId=src.BucketExternalId;

    INSERT dbo.Activities
    (ExternalId,Title,Description,RoleId,WorkflowBucketId,Category,Frequency,Priority,
     ToolCoverageLevel,TriggerContext,McemStage,DurationMinutes,BusinessOutcome,
     BeginnerPrompt,AdvancedPrompt,SuggestedOutputs,SortOrder,IsActive,CreatedAtUtc,UpdatedAtUtc)
    SELECT src.ExternalId,src.Title,src.Description,r.Id,b.Id,src.Category,src.Frequency,
           src.Priority,src.ToolCoverageLevel,src.TriggerContext,src.McemStage,
           src.DurationMinutes,src.BusinessOutcome,src.BeginnerPrompt,src.AdvancedPrompt,
           src.SuggestedOutputs,src.SortOrder,src.IsActive,SYSUTCDATETIME(),NULL
    FROM @Source src
    INNER JOIN dbo.Roles r ON r.ExternalId=src.RoleExternalId
    INNER JOIN dbo.WorkflowBuckets b ON b.ExternalId=src.BucketExternalId
    WHERE NOT EXISTS (SELECT 1 FROM dbo.Activities target WHERE target.ExternalId=src.ExternalId);
    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    THROW;
END CATCH;
GO
